import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation leveraging a bit array and multiple hash functions.

    The optimal size of the bit array and the number of hash functions are calculated based
    on the expected number of items and the desired false positive rate. This implementation
    ensures efficient storage and quick membership testing while minimizing false positives.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        if expected_items <= 0:
            raise ValueError("Expected items must be greater than 0.")
        if not (0 < false_positive_rate < 1):
            raise ValueError("False positive rate must be between 0 and 1.")

        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        self.size = self._optimal_bit_array_size()  # Size of the bit array
        self.num_hashes = self._optimal_num_hash_functions()  # Number of hash functions

        self.bit_array = [0] * self.size  # Initialize the bit array

    def _optimal_bit_array_size(self) -> int:
        """Calculate optimal bit array size."""
        m = (-self.expected_items * math.log(self.false_positive_rate)) / (math.log(2) ** 2)
        return int(math.ceil(m))

    def _optimal_num_hash_functions(self) -> int:
        """Calculate optimal number of hash functions."""
        k = (self.size / self.expected_items) * math.log(2)
        return int(math.ceil(k))

    def _hash(self, item: str, seed: int) -> int:
        """Generate a hash for the item using SHA-256 with a seed for uniqueness."""
        hash_result = hashlib.sha256(f"{item}:{seed}".encode()).hexdigest()
        return int(hash_result, 16) % self.size

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for i in range(self.num_hashes):
            index = self._hash(item, i)
            self.bit_array[index] = 1  # Set the bit at the index to 1

    def contains(self, item: str) -> bool:
        """Check if the item is possibly in the Bloom Filter."""
        for i in range(self.num_hashes):
            index = self._hash(item, i)
            if self.bit_array[index] == 0:
                return False  # Definitely not in the filter
        return True  # Possibly in the filter

